import{_ as e}from"./chunks/ark_v6s_front.Bnt4MIDz.js";import{_ as r,o as a,c as o,al as l}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"ARK Electronics ARKV6S","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_controller/ark_v6s.md","filePath":"zh/flight_controller/ark_v6s.md"}'),i={name:"zh/flight_controller/ark_v6s.md"};function s(n,t,h,d,c,u){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="ark-electronics-arkv6s" tabindex="-1">ARK Electronics ARKV6S <a class="header-anchor" href="#ark-electronics-arkv6s" aria-label="Permalink to &quot;ARK Electronics ARKV6S&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://arkelectron.com/contact-us/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The USA-built <a href="https://arkelectron.gitbook.io/ark-documentation/flight-controllers/arkv6s" target="_blank" rel="noreferrer">ARKV6S</a> flight controller is a low-cost, single-IMU variant of the <a href="./../flight_controller/ark_v6x">ARKV6X</a>, based on the <a href="https://github.com/pixhawk/Pixhawk-Standards" target="_blank" rel="noreferrer">FMUV6X and Pixhawk Autopilot Bus open source standards</a>.</p><p>The Pixhawk Autopilot Bus (PAB) form factor enables the ARKV6S to be used on any <a href="./../flight_controller/pixhawk_autopilot_bus">PAB-compatible carrier board</a>, such as the <a href="./../flight_controller/ark_pab">ARK Pixhawk Autopilot Bus Carrier</a>.</p><p><img src="'+e+'" alt="ARKV6S Main Photo"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="store" tabindex="-1">Where To Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where To Buy {#store}&quot;">​</a></h2><p>Order From <a href="https://arkelectron.com/product/arkv6s-flight-controller/" target="_blank" rel="noreferrer">Ark Electronics</a> (US)</p><h2 id="传感器" tabindex="-1">传感器 <a class="header-anchor" href="#传感器" aria-label="Permalink to &quot;传感器&quot;">​</a></h2><ul><li><a href="https://www.invensense.tdk.com/en-us/products/6-axis/iim-42653" target="_blank" rel="noreferrer">Invensense IIM-42653 Industrial IMU</a></li><li><a href="https://www.bosch-sensortec.com/en/products/environmental-sensors/pressure-sensors/bmp390/" target="_blank" rel="noreferrer">Bosch BMP390 Barometer</a></li><li><a href="https://www.st.com/en/mems-and-sensors/iis2mdc.html" target="_blank" rel="noreferrer">ST IIS2MDC Magnetometer</a></li></ul><h2 id="microprocessor" tabindex="-1">Microprocessor <a class="header-anchor" href="#microprocessor" aria-label="Permalink to &quot;Microprocessor&quot;">​</a></h2><ul><li><a href="https://www.st.com/en/microcontrollers-microprocessors/stm32h743ii.html" target="_blank" rel="noreferrer">STM32H743IIK6 MCU</a><ul><li>480MHz</li><li>2MB Flash</li><li>1MB RAM</li></ul></li></ul><h2 id="other-features" tabindex="-1">Other Features <a class="header-anchor" href="#other-features" aria-label="Permalink to &quot;Other Features&quot;">​</a></h2><ul><li>FRAM</li><li><a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-010%20Pixhawk%20Autopilot%20Bus%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Autopilot Bus (PAB) Form Factor</a></li><li>LED Indicators</li><li>MicroSD Slot</li><li>USA Built</li><li>Designed with a 1W heater. Keeps sensors warm in extreme conditions</li></ul><h2 id="power-requirements" tabindex="-1">Power Requirements <a class="header-anchor" href="#power-requirements" aria-label="Permalink to &quot;Power Requirements&quot;">​</a></h2><ul><li>5V</li><li>500mA <ul><li>300ma for main system</li><li>200ma for heater</li></ul></li></ul><h2 id="附加信息" tabindex="-1">附加信息 <a class="header-anchor" href="#附加信息" aria-label="Permalink to &quot;附加信息&quot;">​</a></h2><ul><li>Weight: 5.0 g</li><li>Dimensions: 3.6 x 2.9 x 0.5 cm</li></ul><h2 id="针脚定义" tabindex="-1">针脚定义 <a class="header-anchor" href="#针脚定义" aria-label="Permalink to &quot;针脚定义&quot;">​</a></h2><p>For pinout of the ARKV6S see the <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-010%20Pixhawk%20Autopilot%20Bus%20Standard.pdf" target="_blank" rel="noreferrer">DS-10 Pixhawk Autopilot Bus Standard</a></p><h2 id="串口映射" tabindex="-1">串口映射 <a class="header-anchor" href="#串口映射" aria-label="Permalink to &quot;串口映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>设备</th><th>Port</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM3</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>调试控制台</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>UART4 &amp; I2C</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TELEM2</td></tr><tr><td>USART6</td><td>/dev/ttyS5</td><td>PX4IO/RC</td></tr><tr><td>UART7</td><td>/dev/ttyS6</td><td>TELEM1</td></tr><tr><td>UART8</td><td>/dev/ttyS7</td><td>GPS2</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The mapping above applies to the running PX4 firmware. The ARKV6S bootloader enables only <code>UART7</code> (TELEM1), so when flashing firmware over UART with <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/px4_uploader.py" target="_blank" rel="noreferrer"><code>px4_uploader.py</code></a> you must connect to the <code>TELEM1</code> port — no other UART will respond in bootloader mode.</p></div><h2 id="编译固件" tabindex="-1">编译固件 <a class="header-anchor" href="#编译固件" aria-label="Permalink to &quot;编译固件&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ark_fmu-v6s_default</span></span></code></pre></div><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="https://arkelectron.gitbook.io/ark-documentation/flight-controllers/arkv6s" target="_blank" rel="noreferrer">ARK Electronics ARKV6S</a> (ARK Docs)</li></ul>',27)])])}const k=r(i,[["render",s]]);export{f as __pageData,k as default};
